head.script:
//
(function() {
    var darkFavicon = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiQsnusVJ6kB8gTAULrKk9JaNddwvwUlw4-6HEZNIiF12IvKnbMAOwdUMrlevN5EKYgnl6LHpKvFZjlDqgZ9WvpNu_rjPzJ473O1rrL9iG_eD4VxA_EZKj2uN_DmIXTzZTKa3kaaB0p821aftNpRXTRZAqZQPqniktfZkVslxDAGMUkP5b3G4cOyAFYpVMn/s1600/dark%20bhajasi%20fevicon192.png';
    var lightFavicon = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEg94LhEYUGaBU0HdY5Cumz3j-nmJ7NdDjBQ5DCKsZd5uBYDTKYFHgQGZ5Iik5cJoBJ2r4pntUVQDJVTI2SvvraMlgW0PVtCOcsx7ebdj2ILBLVEq-nPNy_sfukMA1GE7xfmr28iOBA3JfPy0BJNx08R_DaB6ncp6EFpkJ_o_IyAWZuD6QaTeN4BSMZ_cLkq/s1600/light%20bhajasi%20White%20Spiral%20Logo%20with%20Golden%20Dot.png';

    var matcher = window.matchMedia('(prefers-color-scheme: dark)');

    function applyFavicon() {
        var isDark = matcher.matches;
        var chosenIcon = isDark ? lightFavicon : darkFavicon;

        var icons = document.querySelectorAll("link[rel*='icon']");
        icons.forEach(function(el) {
            el.parentNode.removeChild(el);
        });

        var newIcon = document.createElement('link');
        newIcon.id = 'bhajasi-adaptive-favicon';
        newIcon.rel = 'icon';
        newIcon.type = 'image/png';
        newIcon.href = chosenIcon;
        document.head.appendChild(newIcon);
    }

    applyFavicon();

    try {
        matcher.addEventListener('change', applyFavicon);
    } catch (e) {
        matcher.addListener(applyFavicon);
    }

    document.addEventListener('DOMContentLoaded', applyFavicon);
    window.addEventListener('load', applyFavicon);
})();
