    mirabai: 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhgOlin1SfYdiESeHswdVP0H9AWJ9bbfFH09JyW5fZrL4BWxTki8NKtZS1dDsBikFSAB2rz9BPLoBHMUgtNV2AvbEYKZ3KEQXHIkjv7IyhiXZhT3ZwEXgWR6rYvxpkH4C-Tk60MnSeo9d5GesbhU-YnBfG3lxKdKV19BedRbvRXv9P3VaHFsVn0DchtT0M/s320/mira%20bai.png',
    kalidas: 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEj0IXT1cxzPvNJ_qUI25u-QP356WuGJAi-VAh-21AOhMuGkkJImaHgO-f68lI5-pBnuvDPEKuN4-rlgnyLXUkvvsGOjHfzXhdk3wqegTY7o1sPDdRAHffOXpmEfbuR5SEneRGdXEDjUc8M07jY6HczaztxUm22fOVVu64siJQp6viu4y6JSx9e88eYUyeY/s320/kalidas.png'
};

function getSaintPortrait(saint) {
    if (!saint) return SITE_LOGO;
    if (saint.image || saint.photo || saint.avatar) {
        return saint.image || saint.photo || saint.avatar;
    }
    const id = String(saint.id || '').toLowerCase();
    const name = String(saint.name || '');
    if (SAINT_PORTRAITS[id]) return SAINT_PORTRAITS[id];
    if (name.indexOf('ज्ञानेश्वर') >= 0) return SAINT_PORTRAITS.dnyaneshwar;
    if (name.indexOf('एकनाथ') >= 0) return SAINT_PORTRAITS.eknath;
    if (name.indexOf('तुकाराम') >= 0) return SAINT_PORTRAITS.tukaram;
    if (name.indexOf('रामदास') >= 0) return SAINT_PORTRAITS.ramdas;
    if (name.indexOf('नामदेव') >= 0) return SAINT_PORTRAITS.namdev;
    if (name.indexOf('जनाबाई') >= 0) return SAINT_PORTRAITS.janabai;
    if (name.indexOf('सावता') >= 0) return SAINT_PORTRAITS.savata;
    if (name.indexOf('गाडगे') >= 0) return SAINT_PORTRAITS.gadge;
    if (name.indexOf('तुकडोजी') >= 0) return SAINT_PORTRAITS.tukdoji;
    if (name.indexOf('कबीर') >= 0) return SAINT_PORTRAITS.kabir;
    if (name.indexOf('मीरा') >= 0) return SAINT_PORTRAITS.mirabai;
    if (name.indexOf('कालिदास') >= 0) return SAINT_PORTRAITS.kalidas;
    return SITE_LOGO;
}

function getBookCoverStyle(work, index) {
    const palettes = [
        'linear-gradient(145deg, #581c87, #1e1b4b)',
        'linear-gradient(145deg, #7c2d12, #3b0764)',
        'linear-gradient(145deg, #065f46, #134e4a)',
        'linear-gradient(145deg, #831843, #31102f)',
        'linear-gradient(145deg, #1e3a8a, #172554)',
        'linear-gradient(145deg, #78350f, #451a03)'
    ];
    return palettes[(index || 0) % palettes.length];
}

function getThemeIcon(title) {
    const t = String(title || '');
    if (t.indexOf('नाम') >= 0) return 'fa-solid fa-om';
    if (t.indexOf('भक्ती') >= 0) return 'fa-solid fa-hands-praying';
    if (t.indexOf('ज्ञान') >= 0) return 'fa-solid fa-sun';
    if (t.indexOf('समता') >= 0) return 'fa-solid fa-scale-balanced';
    if (t.indexOf('सेवा') >= 0) return 'fa-solid fa-hand-holding-heart';
    if (t.indexOf('वैराग्य') >= 0) return 'fa-solid fa-fire-flame-curved';
    if (t.indexOf('सदाचार') >= 0) return 'fa-solid fa-compass';
    return 'fa-solid fa-spa';
}

/* Image & Native Share Helpers */
async function loadLogoImage(src) {
    return new Promise(function(resolve) {
        if (!src) {
            resolve(null);
            return;
        }
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = function() { resolve(img); };
        img.onerror = function() { resolve(null); };
        img.src = src;
    });
}

async function shareImageFileNative(file, title, text) {
    try {
        if (navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({
                files: [file],
                title: title || 'भजसी भारत .com',
                text: text || ''
            });
            return true;
        }
    } catch (err) {
        if (err && err.name === 'AbortError') return false;
    }

    try {
        const url = URL.createObjectURL(file);
        const a = document.createElement('a');
        a.href = url;
        a.download = file.name || 'bhajasi-share.png';
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(function() { URL.revokeObjectURL(url); }, 1500);
        return true;
    } catch (e) {
        return false;
    }
}

async function shareVerseSnap(entry, index, work, saint, parentWork) {
    if (!entry) return;

    const label = getVerseLabel(entry, index, work);
    const workTitle = getReaderTitle(work, parentWork);
    const saintName = saint && saint.name ? saint.name : 'नित्य पठण';
    const verseText = String(entry.text || entry.original || entry.content || '').trim();
    const meaningText = String(entry.meaning || entry.arth || entry.translation || '').trim();
    const teachingText = String(entry.teaching || entry.shikavan || entry.lesson || '').trim();

    const shareCaption =
        '*' + saintName + ' — ' + workTitle + ' (' + label + ')*\n\n' +
        verseText +
        (meaningText ? '\n\n*भावार्थ:* ' + meaningText : '') +
        (teachingText ? '\n\n*शिकवण:* ' + teachingText : '') +
        '\n\nभजसी भारत .com — संकलन: भरत रासवे\n' + SITE_URL;

    const width = 1080;
    const padding = 76;
    const contentWidth = width - padding * 2;
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    if (document.fonts && document.fonts.ready) {
        try {
            await document.fonts.ready;
            await Promise.all([
                document.fonts.load('700 38px "Tiro Devanagari Marathi"'),
                document.fonts.load('700 40px "Laila"'),
                document.fonts.load('400 29px "Noto Sans Devanagari"'),
                document.fonts.load('700 22px "Noto Sans Devanagari"'),
                document.fonts.load('700 30px "Alkatra"')
            ]);
        } catch (e) {}
    }

    function wrap(textValue, font, maxWidth) {
        if (!textValue) return [];
        ctx.font = font;
        const words = String(textValue).split(/\s+/u);
        const result = [];
        let current = '';
        words.forEach(function(word) {
            if (!word) return;
            const candidate = current ? current + ' ' + word : word;
            if (ctx.measureText(candidate).width > maxWidth && current) {
                result.push(current);
                current = word;
            } else {
                current = candidate;
            }
        });
        if (current) result.push(current);
        return result;
    }

    // Split poem lines cleanly
    const rawPoemLines = splitPoem(verseText);
    const wrappedPoemLines = [];
    rawPoemLines.forEach(function(line) {
        wrap(line, '700 40px "Laila", "Noto Serif Devanagari", serif', contentWidth - 40)
            .forEach(function(subLine) {
                wrappedPoemLines.push(subLine);
            });
    });

    const meaningLines = wrap(meaningText, '400 29px "Noto Sans Devanagari", sans-serif', contentWidth);
    const teachingLines = wrap(teachingText, '400 29px "Noto Sans Devanagari", sans-serif', contentWidth);

    const poemBlock = Math.max(wrappedPoemLines.length, 1) * 62;
    // Extra vertical breathing room for meaning & teaching sections
    const meaningBlock = meaningLines.length ? (meaningLines.length * 48 + 120) : 0;
    const teachingBlock = teachingLines.length ? (teachingLines.length * 48 + 120) : 0;
    const topBlock = 290;
    const footerBlock = 220;

    const height = Math.max(1150, topBlock + poemBlock + meaningBlock + teachingBlock + footerBlock + 80);

    canvas.width = width;
    canvas.height = height;

    // Dark Navy Gradient Background
    const bgGrad = ctx.createLinearGradient(0, 0, width, height);
    bgGrad.addColorStop(0, '#2a3950');
    bgGrad.addColorStop(0.48, '#1e2838');
    bgGrad.addColorStop(1, '#151d2a');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, width, height);

    // Multi-stop Golden Outer Frame
    const frameGradient = ctx.createLinearGradient(0, 24, width, height - 24);
    frameGradient.addColorStop(0, '#ffcf33');
    frameGradient.addColorStop(0.24, '#f59e0b');
    frameGradient.addColorStop(0.50, '#fff0a3');
    frameGradient.addColorStop(0.72, '#e98006');
    frameGradient.addColorStop(1, '#ffd24a');
    ctx.strokeStyle = frameGradient;
    ctx.lineWidth = 4;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(18, 18, width - 36, height - 36, 25);
    else ctx.rect(18, 18, width - 36, height - 36);
    ctx.stroke();

    // Inner Subtle Highlight Line
    ctx.save();
    ctx.globalAlpha = 0.32;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(21, 21, width - 42, height - 42, 22);
    else ctx.rect(21, 21, width - 42, height - 42);
    ctx.stroke();
    ctx.restore();

    // Center Spiral Watermark Logo
    const watermarkImg = await loadLogoImage(SITE_LOGO);
    if (watermarkImg && watermarkImg.naturalWidth) {
        const wmSize = 440;
        const ratio = watermarkImg.naturalWidth / Math.max(1, watermarkImg.naturalHeight);
        const wmW = wmSize;
        const wmH = wmSize / Math.max(0.1, ratio);
        ctx.save();
        ctx.globalAlpha = 0.075;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(watermarkImg, (width - wmW) / 2, (height - wmH) / 2 - 30, wmW, wmH);
        ctx.restore();
    }

    // Top Header: Saint & Work Title
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    ctx.fillStyle = '#e98006';
    ctx.font = '700 36px "Tiro Devanagari Marathi", serif';
    ctx.fillText(saintName + ' • ' + workTitle, width / 2, 90);

    // Work / Section Pill Box
    const subLabelText = workTitle;
    ctx.font = '700 26px "Noto Sans Devanagari", sans-serif';
    const subLabelW = ctx.measureText(subLabelText).width;
    const subBoxW = Math.min(contentWidth - 60, subLabelW + 64);
    const subBoxH = 52;
    const subBoxX = (width - subBoxW) / 2;
    const subBoxY = 114;

    const labelGradient = ctx.createLinearGradient(subBoxX, subBoxY, subBoxX + subBoxW, subBoxY + subBoxH);
    labelGradient.addColorStop(0, '#f6a80b');
    labelGradient.addColorStop(0.5, '#ffd45a');
    labelGradient.addColorStop(1, '#e98006');
    ctx.strokeStyle = labelGradient;
    ctx.lineWidth = 2.5;
    ctx.fillStyle = 'rgba(65,67,106,.45)';
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(subBoxX, subBoxY, subBoxW, subBoxH, 15);
    else ctx.rect(subBoxX, subBoxY, subBoxW, subBoxH);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#ffffff';
    ctx.fillText(subLabelText, width / 2, subBoxY + 36);

    let y = 215;

    // Verse Badge Pill (e.g., रचना १ / श्लोक २ / अभंग १)
    if (label) {
        ctx.font = '700 23px "Noto Sans Devanagari", sans-serif';
        const badgeW = ctx.measureText(label).width + 36;
        const badgeH = 42;
        ctx.strokeStyle = 'rgba(233,128,6,0.85)';
        ctx.lineWidth = 2;
        ctx.fillStyle = 'rgba(233,128,6,0.18)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(padding, y - 28, badgeW, badgeH, 12);
        else ctx.rect(padding, y - 28, badgeW, badgeH);
        ctx.fill();
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.fillStyle = '#fbd52d';
        ctx.fillText(label, padding + 18, y);
        y += 48;
    }

    // Centered Sacred Poetry Verses
    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffffff';
    ctx.font = '700 40px "Laila", "Noto Serif Devanagari", serif';
    wrappedPoemLines.forEach(function(line) {
        ctx.fillText(line, width / 2, y + 15);
        y += 62;
    });

    // Meaning (भावार्थ) with Generous Bottom Padding
    if (meaningLines.length) {
        y += 24;
        ctx.font = '700 20px "Noto Sans Devanagari", sans-serif';
        const bW = ctx.measureText('भावार्थ').width + 32;
        ctx.strokeStyle = '#30c5ad';
        ctx.lineWidth = 1.5;
        ctx.fillStyle = 'rgba(48,197,173,0.18)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(padding, y - 24, bW, 36, 10);
        else ctx.rect(padding, y - 24, bW, 36);
        ctx.fill();
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.fillStyle = '#30c5ad';
        ctx.fillText('भावार्थ', padding + 16, y);
        y += 48; // Spacing between pill badge and text

        ctx.fillStyle = '#e2e8f0';
        ctx.font = '400 29px "Noto Sans Devanagari", sans-serif';
        meaningLines.forEach(function(line) {
            ctx.fillText(line, padding, y);
            y += 46;
        });
        y += 34; // Generous bottom padding after भावार्थ block
    }

    // Teaching (शिकवण) with Generous Bottom Padding
    if (teachingLines.length) {
        y += 24;
        ctx.font = '700 20px "Noto Sans Devanagari", sans-serif';
        const bW = ctx.measureText('शिकवण').width + 32;
        ctx.strokeStyle = '#fbd52d';
        ctx.lineWidth = 1.5;
        ctx.fillStyle = 'rgba(251,213,45,0.18)';
        ctx.beginPath();
        if (ctx.roundRect) ctx.roundRect(padding, y - 24, bW, 36, 10);
        else ctx.rect(padding, y - 24, bW, 36);
        ctx.fill();
        ctx.stroke();

        ctx.textAlign = 'left';
        ctx.fillStyle = '#fbd52d';
        ctx.fillText('शिकवण', padding + 16, y);
        y += 48; // Spacing between pill badge and text

        ctx.fillStyle = '#f1f5f9';
        ctx.font = '400 29px "Noto Sans Devanagari", sans-serif';
        teachingLines.forEach(function(line) {
            ctx.fillText(line, padding, y);
            y += 46;
        });
        y += 34; // Generous bottom padding after शिकवण block
    }

    // Bottom Branding Plate
    const footerStripY = height - 196;
    ctx.fillStyle = '#0d1624';
    ctx.fillRect(24, footerStripY, width - 48, 172);

    const footerY = height - 176;
    ctx.strokeStyle = 'rgba(148,163,184,.25)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, footerY);
    ctx.lineTo(width - padding, footerY);
    ctx.stroke();

    // Footer Logo (Reliable Image Loader with Cross-Origin & Decode)
    const footerLogoImg = await (async function() {
        return new Promise(function(resolve) {
            const img = new Image();
            img.crossOrigin = 'anonymous';
            img.onload = async function() {
                try { if (img.decode) await img.decode(); } catch(e){}
                resolve(img);
            };
            img.onerror = function() { resolve(null); };
            img.src = FOOTER_LOGO;
        });
    })();

    const footerLogoSize = 64;
    const footerLogoBoxSize = 84;
    const footerLogoX = padding;
    const footerLogoBoxY = height - 152;
    const footerLogoY = footerLogoBoxY + (footerLogoBoxSize - footerLogoSize) / 2;

    // White Rounded Icon Box
    ctx.save();
    ctx.fillStyle = '#ffffff';
    if (ctx.roundRect) {
        ctx.beginPath();
        ctx.roundRect(footerLogoX - 5, footerLogoBoxY, footerLogoBoxSize, footerLogoBoxSize, 14);
        ctx.fill();
    } else {
        ctx.fillRect(footerLogoX - 5, footerLogoBoxY, footerLogoBoxSize, footerLogoBoxSize);
    }
    ctx.restore();

    if (footerLogoImg && footerLogoImg.naturalWidth) {
        const ratio = footerLogoImg.naturalWidth / Math.max(1, footerLogoImg.naturalHeight);
        const footerLogoW = footerLogoSize;
        const footerLogoH = footerLogoSize / Math.max(0.1, ratio);
        ctx.drawImage(footerLogoImg, footerLogoX + 5, footerLogoY, footerLogoW, footerLogoH);
    }

    // Footer Typography
    ctx.textAlign = 'left';
    ctx.fillStyle = '#e98006';
    ctx.font = '700 30px "Alkatra", cursive';
    ctx.fillText('भजसी भारत .com', footerLogoX + 100, height - 108);

    ctx.fillStyle = '#d8dee8';
    ctx.font = '400 22px "Noto Sans Devanagari", sans-serif';
    ctx.fillText('(संतवाणी • ग्रंथ • हरिनाम • चिंतन • स्तोत्र)', footerLogoX + 100, height - 76);

    ctx.textAlign = 'right';
    ctx.fillStyle = '#f1f5f9';
    ctx.font = '500 21px "Noto Sans Devanagari", sans-serif';
    ctx.fillText('निर्मिती आणि संकलन: भरत रासवे', width - padding, height - 108);

    ctx.fillStyle = '#30c5ad';
    ctx.font = '400 20px "Noto Sans Devanagari", sans-serif';
    ctx.fillText('वेबसाईटला भेट द्या: bhajasibharat.blogspot.com', width - padding, height - 76);

    let blob = null;
    try {
        blob = await new Promise(function(resolve) {
            canvas.toBlob(resolve, 'image/png', 1.0);
        });
    } catch (e) {}

    if (!blob) {
        const waUrl = 'https://wa.me/?text=' + encodeURIComponent(shareCaption);
        window.open(waUrl, '_blank', 'noopener,noreferrer');
        return;
    }

    const file = new File([blob], 'bhajasi-rachana.png', { type: 'image/png' });
    await shareImageFileNative(file, saintName + ' — ' + workTitle, shareCaption);
}

const PROGRESS_KEY = 'bhajasi_reading_progress_v2';
const NOTIFY_KEY = 'bhajasi_notification_v1';
const EXAM_RESULT_KEY = 'bhajasi_pariksha_results_v1';
const EXAM_PROGRESS_KEY = 'bhajasi_pariksha_progress_v1';

const {
    useState,
    useEffect,
    useMemo,
    useRef
} = React;

const CONTENT_KEYS = [
    'entries',
    'verses',
    'ovis',
    'abhangs',
    'shloks',
    'stanzas'
];

function safeJSON(value, fallback) {
    try {
        return JSON.parse(value);
    } catch (e) {
        return fallback;
    }
}

function readProgress() {
    return safeJSON(localStorage.getItem(PROGRESS_KEY) || '{}', {});
}

function readExamProgress() {
    return safeJSON(localStorage.getItem(EXAM_PROGRESS_KEY) || '{}', {});
}

function getExamQuestionKey(question, index) {
    if (question && question.id !== undefined && question.id !== null && String(question.id).trim()) {
        return String(question.id);
    }
    if (question && question.questionId !== undefined && question.questionId !== null && String(question.questionId).trim()) {
        return String(question.questionId);
    }
    return 'index:' + String(index);
}

function persistExamProgress(exam, questions, questionIndex, answers, startedAt) {
    if (!exam || !exam.id) return;
    const progress = readExamProgress();
    const questionIds = (questions || []).map(function(question, index) {
        return getExamQuestionKey(question, index);
    });
    const existing = progress[exam.id] || {};
    progress[exam.id] = {
        examId: exam.id,
        title: exam.title || '',
        file: exam.file || '',
        questionIds: questionIds,
        currentQuestionIndex: Math.max(0, Math.min(Number(questionIndex || 0), Math.max(0, questionIds.length - 1))),
        answers: Object.assign({}, answers || {}),
        startedAt: startedAt || existing.startedAt || new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };
    localStorage.setItem(EXAM_PROGRESS_KEY, JSON.stringify(progress));
}

function clearExamProgress(examId) {
    if (!examId) return;
    const progress = readExamProgress();
    if (progress[examId]) {
        delete progress[examId];
        localStorage.setItem(EXAM_PROGRESS_KEY, JSON.stringify(progress));
    }
}

function writeProgress(key, value) {
    const old = readProgress();
    old[key] = Object.assign({}, old[key] || {}, value);
    localStorage.setItem(PROGRESS_KEY, JSON.stringify(old));
}

function makeWorkKey(saint, work) {
    return String(saint && saint.id || '') + '::' +
        String(work && (work.id || work.file || work.title) || '');
}

function toMarathiDigits(num) {
    if (num === null || num === undefined || num === '') return '';
    const digits = ['०','१','२','३','४','५','६','७','८','९'];
    return String(num).replace(/[0-9]/g, function(d) {
        return digits[d];
    });
}

function getVerseLabel(entry, index, work) {
    if (!entry) return '';
    if (entry.label || entry.typeLabel) {
        return entry.label || entry.typeLabel;
    }

    let value = '';
    if (entry.number !== undefined && entry.number !== null) {
        value = toMarathiDigits(entry.number);
    } else if (entry.id) {
        const match = String(entry.id).match(/(\d+)$/);
        if (match) value = toMarathiDigits(parseInt(match[1], 10));
    }
    if (!value) {
        const textMatch = String(entry.text || '').match(
            /॥\s*([०-९0-9]+(?:-[०-९0-9]+)?)\s*॥/u
        );
        if (textMatch) value = toMarathiDigits(textMatch[1]);
    }
    if (!value) value = toMarathiDigits(index + 1);

    const type = String(
        entry.type ||
        entry.kind ||
        (work && work.type) ||
        ''
    ).toLowerCase();

    if (type.indexOf('अभंग') >= 0 || type.indexOf('abhang') >= 0) return 'अभंग ' + value;
    if (type.indexOf('श्लोक') >= 0 || type.indexOf('shlok') >= 0 || type.indexOf('स्तोत्र') >= 0) return 'श्लोक ' + value;
    if (type.indexOf('पद') >= 0 || type.indexOf('pad') >= 0) return 'पद ' + value;
    if (type.indexOf('दोहा') >= 0 || type.indexOf('doha') >= 0) return 'दोहा ' + value;
    if (type.indexOf('ओवी') >= 0 || type.indexOf('ovi') >= 0 || type.indexOf('ग्रंथ') >= 0) return 'ओवी ' + value;

    return 'रचना ' + value;
}

function splitPoem(text) {
    if (!text) return [];
    const normalized = String(text).replace(/\r\n/g, '\n').trim();
    if (!normalized) return [];

    const lines = normalized.split('\n').map(function(line) { return line.trim(); }).filter(Boolean);
    if (lines.length > 1) return lines;

    const clauses = normalized.split(/(?<=।)\s+/u).map(function(x) { return x.trim(); }).filter(Boolean);
    if (clauses.length <= 2) return clauses;

    const grouped = [];
    for (let i = 0; i < clauses.length; i += 2) {
        grouped.push(clauses.slice(i, i + 2).join(' '));
    }
    return grouped;
}

function normalizeContent(raw) {
    if (Array.isArray(raw)) return { entries: raw, days: 1 };
    if (!raw || typeof raw !== 'object') return { entries: [], days: 1 };

    let entries = [];
    CONTENT_KEYS.some(function(key) {
        if (Array.isArray(raw[key])) {
            entries = raw[key];
            return true;
        }
        return false;
    });

    if (!entries.length && Array.isArray(raw.content)) {
        entries = raw.content;
    }

    return Object.assign({}, raw, {
        entries: entries,
        days: Number(raw.days || 1)
    });
}

async function fetchJSON(url) {
    const response = await fetch(
        url + (url.indexOf('?') >= 0 ? '&' : '?') + 'v=' + Date.now(),
        {
            cache: 'no-store',
            headers: { 'Accept': 'application/json' }
        }
    );
    if (!response.ok) throw new Error('HTTP ' + response.status + ': ' + url);
    return response.json();
}

function resolveURL(kind, file) {
    if (!file) return '';
    if (/^https?:\/\//i.test(file)) return file;
    if (kind === 'nitya') return NITYA_BASE + file.replace(/^nitya-pathan\//, '');
    return SAINTS_BASE + file.replace(/^saints\//, '');
}

function workHasSections(work) {
    return !!(work && Array.isArray(work.sections) && work.sections.length);
}

function getSectionDisplaySubtitle(section) {
    if (!section) return '';
    return String(
        section.subtitle ||
        section.name ||
        section.description ||
        section.topic ||
        ''
    ).trim();
}

function getWorkSummary(work) {
    if (!work) return '';
    if (work.description) return work.description;
    if (work.type) return work.type;
    if (work.days) return 'दिवस ' + toMarathiDigits(work.days);
    if (work.sections) return toMarathiDigits(work.sections.length) + ' विभाग';
    return '';
}

function formatSubTitle(title, parentTitle) {
    if (!title) return '';
    if (parentTitle && title.indexOf(parentTitle) === 0) {
        return title.replace(
            new RegExp('^' + parentTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*[-—–]?\\s*', 'u'),
            ''
        ).trim() || title;
    }
    return title;
}

/* Metadata-aware title used by the reader and image shares. */
function getReaderTitle(work, parentWork) {
    if (!work) return '';
    const baseTitle = String(work.title || '').trim();
    const subtitle = String(work.subtitle || '').trim();
    if (subtitle) return baseTitle + ' – ' + subtitle;
    return baseTitle;
}

function flattenContentForSearch(content) {
    const data = normalizeContent(content);
    return data.entries.map(function(entry, index) {
        return {
            entry: entry,
            index: index,
            text: [
                entry.text,
                entry.meaning,
                entry.teaching,
                entry.commentary,
                entry.translation
            ].filter(Boolean).join(' ')
        };
    });
}

function entryBelongsToDay(entry, day) {
    if (entry.day === undefined || entry.day === null || entry.day === '') {
        return Number(day) === 1;
    }
    return Number(entry.day) === Number(day);
}

function getEntriesForDay(content, day) {
    const data = normalizeContent(content);
    if (!data.entries.length) return [];
    const hasDayData = data.entries.some(function(entry) {
        return entry.day !== undefined && entry.day !== null;
    });
    if (!hasDayData) return data.entries;
    return data.entries.filter(function(entry) {
        return entryBelongsToDay(entry, day);
    });
}

function getTotalDays(work, content) {
    const data = normalizeContent(content);
    const fromWork = Number(work && work.days || 0);
    const fromContent = Number(data.days || 0);
    const entryDays = data.entries
        .map(function(entry) { return Number(entry.day || 0); })
        .filter(Boolean);
    const fromEntries = entryDays.length ? Math.max.apply(Math, entryDays) : 1;
    return Math.max(1, fromWork, fromContent, fromEntries);
}

function expandHaripath(entries, workTitle) {
    return entries || [];
}

function localDateKey(date) {
    const value = date instanceof Date ? date : new Date();
    const year = value.getFullYear();
    const month = String(value.getMonth() + 1).padStart(2, '0');
    const day = String(value.getDate()).padStart(2, '0');
    return year + '-' + month + '-' + day;
}

function getDailyNityaIndex(length) {
    if (!length) return 0;
    const start = new Date(new Date().getFullYear(), 0, 0);
    const now = new Date();
    const dayOfYear = Math.floor((now - start) / 86400000);
    return (dayOfYear - 1) % length;
}

function getProgressItems(saints) {
    const progress = readProgress();
    const result = [];

    (saints || []).forEach(function(saint) {
        (saint.works || []).forEach(function(work) {
            if (workHasSections(work)) {
                work.sections.forEach(function(section) {
                    const saved = progress[makeWorkKey(saint, section)];
                    if (saved) {
                        result.push({
                            saint: saint,
                            work: section,
                            parentWork: work,
                            day: Number(saved.day || 1),
                            updatedAt: Number(saved.updatedAt || 0)
                        });
                    }
                });
            } else {
                const saved = progress[makeWorkKey(saint, work)];
                if (saved) {
                    result.push({
                        saint: saint,
                        work: work,
                        parentWork: null,
                        day: Number(saved.day || 1),
                        updatedAt: Number(saved.updatedAt || 0)
                    });
                }
            }
        });
    });

    return result.sort(function(a, b) {
        return b.updatedAt - a.updatedAt;
    });
}

function topLevelWorks(saints) {
    return (saints || []).flatMap(function(saint) {
        return (saint.works || []).map(function(work, index) {
            return {
                saint: saint,
                work: work,
                index: index
            };
        });
    });
}

function getSaintCardSummary(saint) {
    return (saint && Array.isArray(saint.works) ? saint.works : [])
        .map(function(work) {
            return work && work.title ? work.title : '';
        })
        .filter(Boolean)
        .join(' • ');
}

function buildMetadataSearch(saints, nitya) {
    const results = [];

    (saints || []).forEach(function(saint) {
        const saintSearchText = [
            saint.name,
            saint.search,
            saint.description
        ].filter(Boolean).join(' ');

        results.push({
            type: 'saint',
            title: saint.name || saint.id,
            sub: 'संत • ग्रंथसूची',
            searchText: saintSearchText,
            saint: saint
        });

        (saint.works || []).forEach(function(work) {
            const workSearchText = [
                work.title,
                work.subtitle,
                work.name,
                work.description,
                work.topic,
                work.type,
                work.search,
                saintSearchText
            ].filter(Boolean).join(' ');

            results.push({
                type: 'work',
                title: work.title || work.id,
                sub: [saint.name, work.type].filter(Boolean).join(' • '),
                searchText: workSearchText,
                saint: saint,
                work: work
            });

            if (work.themeIndex && Array.isArray(work.themeIndex.themes)) {
                results.push({
                    type: 'themeIndex',
                    title: work.themeIndex.title || 'विषयानुसार गाथा',
                    sub: [work.themeIndex.type, work.title].filter(Boolean).join(' • '),
                    searchText: [work.themeIndex.title, work.themeIndex.description, work.title, work.type, saintSearchText].filter(Boolean).join(' '),
                    saint: saint,
                    work: work,
                    themeIndex: work.themeIndex
                });
                work.themeIndex.themes.forEach(function(theme) {
                    results.push({
                        type: 'theme',
                        title: theme.title || theme.id,
                        sub: [theme.type, work.themeIndex.title, work.title].filter(Boolean).join(' • '),
                        searchText: [theme.title, theme.type, theme.description, work.themeIndex.title, work.title, saintSearchText].filter(Boolean).join(' '),
                        saint: saint,
                        work: work,
                        themeIndex: work.themeIndex,
                        theme: theme
                    });
                });
            }

            (work.sections || []).forEach(function(section) {
                const sectionSubtitle = getSectionDisplaySubtitle(section);
                const sectionSearchText = [
                    section.title,
                    section.subtitle,
                    section.name,
                    section.description,
                    section.topic,
                    section.type,
                    section.search,
                    work.title,
                    work.subtitle,
                    work.name,
                    work.description,
                    work.topic,
                    work.search,
                    saintSearchText
                ].filter(Boolean).join(' ');

                results.push({
                    type: 'section',
                    title: section.title || section.id,
                    sub: [sectionSubtitle, work.title, saint.name].filter(Boolean).join(' • '),
                    searchText: sectionSearchText,
                    saint: saint,
                    work: section,
                    parentWork: work
                });
            });
        });
    });

    ((nitya && nitya.works) || []).forEach(function(work) {
        const nityaSearchText = [
            work.title,
            work.subtitle,
            work.name,
            work.description,
            work.topic,
            work.type,
            work.search
        ].filter(Boolean).join(' ');

        results.push({
            type: 'nitya',
            title: work.title || work.id,
            sub: ['नित्य पठण', work.type].filter(Boolean).join(' • '),
            searchText: nityaSearchText,
            nityaWork: work
        });
    });

    return results;
}

