        navigate('books');
    }

    function jumpHomeSection(id) {
        setView('home');
        setTimeout(function() {
            const target = document.getElementById(id);
            if (target) {
                target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        }, 30);
    }

    function nextDay() {
        if (!selectedWork && !selectedNityaWork) return;
        const total = getTotalDays(selectedWork || selectedNityaWork, selectedContent);
        if (day >= total) return;

        const next = day + 1;
        setDay(next);

        if (selectedWork && selectedSaint) {
            writeProgress(
                makeWorkKey(selectedSaint, selectedWork),
                { day: next, updatedAt: Date.now() }
            );
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function previousDay() {
        if (day <= 1) return;

        const previous = day - 1;
        setDay(previous);

        if (selectedWork && selectedSaint) {
            writeProgress(
                makeWorkKey(selectedSaint, selectedWork),
                { day: previous, updatedAt: Date.now() }
            );
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function onTouchStart(event) {
        if (view !== 'reader' && view !== 'nityaReader') return;
        touchStart.current = event.changedTouches[0].clientX;
    }

    function onTouchEnd(event) {
        if ((view !== 'reader' && view !== 'nityaReader') || touchStart.current === null) return;
        const end = event.changedTouches[0].clientX;
        const distance = end - touchStart.current;

        if (Math.abs(distance) < 55) {
            touchStart.current = null;
            return;
        }

        if (distance < 0) nextDay();
        else previousDay();

        touchStart.current = null;
    }

    function handleShare() {
        const shareData = {
            title: 'भजसी भारत .com — संतवाणी',
            text: 'संतसाहित्याचे शांत वाचन, सार्थ ज्ञानेश्वरी, हरिपाठ, गाथा आणि नित्य पठण.',
            url: SITE_URL
        };

        if (navigator.share) {
            navigator.share(shareData).catch(function() {});
            return;
        }

        if (navigator.clipboard) {
            navigator.clipboard.writeText(SITE_URL)
                .then(function() { alert('भजसी भारत लिंक कॉपी झाली आहे.'); })
                .catch(function() { alert(SITE_URL); });
        } else {
            alert(SITE_URL);
        }
    }

    async function searchContent(query) {
        const q = String(query || '').trim().toLowerCase();
        if (q.length < 2) {
            setSearchResults([]);
            setSearchLoading(false);
            return;
        }

        const metadata = buildMetadataSearch(saints, nitya);
        const quick = metadata.filter(function(item) {
            return String(
                item.searchText ||
                [
                    item.title,
                    item.sub,
                    item.saint && item.saint.search,
                    item.work && item.work.search,
                    item.nityaWork && item.nityaWork.search
                ].filter(Boolean).join(' ')
            ).toLowerCase().indexOf(q) >= 0;
        }).slice(0, 20);

        setSearchResults(quick);
        setSearchLoading(true);

        const candidates = metadata.filter(function(item) {
            return (item.type === 'work' || item.type === 'section' || item.type === 'nitya');
        });

        const contentMatches = [];

        await Promise.all(
            candidates.map(async function(item) {
                try {
                    const work = item.work || item.nityaWork;
                    const kind = item.type === 'nitya' ? 'nitya' : 'saint';
                    const content = await loadWorkContent(work, kind);

                    flattenContentForSearch(content).forEach(function(found) {
                        if (found.text && found.text.toLowerCase().indexOf(q) >= 0) {
                            contentMatches.push({
                                type: 'verse',
                                title: (item.title || work.title) + ' • ' + getVerseLabel(found.entry, found.index, work),
                                sub: String(found.entry.text || '').replace(/\s+/g, ' ').slice(0, 100),
                                saint: item.saint || null,
                                work: work,
                                parentWork: item.parentWork || null,
                                nityaWork: item.nityaWork || null,
                                day: Number(found.entry.day || 1)
                            });
                        }
                    });
                } catch (error) {}
            })
        );

        const combined = quick.concat(contentMatches);
        const seen = {};
        const unique = combined.filter(function(item) {
            const key = item.type + '::' + item.title + '::' + item.sub;
            if (seen[key]) return false;
            seen[key] = true;
            return true;
        });

        setSearchResults(unique.slice(0, 30));
        setSearchLoading(false);
    }

    useEffect(function() {
        const timer = setTimeout(function() { searchContent(search); }, 350);
        return function() { clearTimeout(timer); };
    }, [search, saints, nitya]);

    useEffect(function() {
        const hasSharedExamURL = (function() {
            try {
                const params = new URLSearchParams(window.location.search || '');
                const hasQuestionURL = !!(params.get('bhajasiExam') && params.get('bhajasiQuestion') !== null);
                const navigationEntry = window.performance &&
                    typeof window.performance.getEntriesByType === 'function'
                    ? window.performance.getEntriesByType('navigation')[0]
                    : null;
                const isBrowserReload = !!(navigationEntry && navigationEntry.type === 'reload');

                return hasQuestionURL && !isBrowserReload;
            } catch (e) {
                return false;
            }
        })();

        if (!hasSharedExamURL) {
            setView('home');
            setSelectedExam(null);
            setExamQuestions([]);
            setExamQuestionIndex(0);
            setExamAnswers({});
            setExamSubmitted(false);
            setExamResult(null);
            setCertificateName('');
            setCertificatePreview('');
            setCertificateId('');
            setExamSourceReturn(false);
        }

        function handlePageShow(event) {
            if (!event.persisted || hasSharedExamURL) return;
            setView('home');
            setSelectedExam(null);
            setExamQuestions([]);
            setExamQuestionIndex(0);
            setExamAnswers({});
            setExamSubmitted(false);
            setExamResult(null);
            setCertificateName('');
            setCertificatePreview('');
            setCertificateId('');
            setExamSourceReturn(false);
            window.scrollTo({ top: 0, behavior: 'auto' });
        }

        window.addEventListener('pageshow', handlePageShow);
        return function() {
            window.removeEventListener('pageshow', handlePageShow);
        };
    }, []);

    useEffect(function() {
        if (!pariksha || !Array.isArray(pariksha.exams)) return;

        const navigationEntry = window.performance &&
            typeof window.performance.getEntriesByType === 'function'
            ? window.performance.getEntriesByType('navigation')[0]
            : null;
        const isBrowserReload = !!(navigationEntry && navigationEntry.type === 'reload');
        if (isBrowserReload) return;

        const params = new URLSearchParams(window.location.search || '');
        const examId = params.get('bhajasiExam');
        const questionIndex = params.get('bhajasiQuestion');
        if (!examId || questionIndex === null) return;
        openSharedExamQuestion(examId, questionIndex);
    }, [pariksha]);

    function activateSearchResult(item) {
        setSearch('');
        setGlobalSearchOpen(false);

        if (item.type === 'saint') {
            openSaint(item.saint);
            return;
        }
        if (item.type === 'work') {
            handleWorkClick(item.saint, item.work, null);
            return;
        }
        if (item.type === 'themeIndex' || item.type === 'theme') {
            openThemeIndex(item.saint, item.work);
            return;
        }
        if (item.type === 'section') {
            handleWorkClick(item.saint, item.work, item.parentWork);
            return;
        }
        if (item.type === 'nitya') {
            openWork(null, item.nityaWork, 1, null, 'nitya');
            return;
        }
        if (item.type === 'verse') {
            if (item.nityaWork) {
                openWork(null, item.nityaWork, item.day, null, 'nitya');
            } else {
                openWork(item.saint, item.work, item.day, item.parentWork || null, 'saint');
            }
        }
    }

    const filteredSaints = useMemo(function() {
        const q = search.trim().toLowerCase();
