        const courtesyTextW=courtesyW+22+noteW;
        const courtesyGroupW=courtesyLogoSize+courtesyGap+courtesyTextW;
        const courtesyStart=800-courtesyGroupW/2;
        if(logoImg && logoImg.naturalWidth){
            const ratio=logoImg.naturalWidth/Math.max(1,logoImg.naturalHeight);
            const logoW=courtesyLogoSize;
            const logoH=courtesyLogoSize/Math.max(.1,ratio);
            ctx.drawImage(logoImg,courtesyStart,78,logoW,logoH);
        }
        ctx.textAlign='left';
        ctx.fillStyle='#7b5a10';
        ctx.font='700 44px "Alkatra", cursive';
        ctx.fillText(courtesy,courtesyStart+courtesyLogoSize+courtesyGap,108);
        ctx.fillStyle='#59636b';
        ctx.font='600 23px "Hind", sans-serif';
        ctx.fillText(courtesyNote,courtesyStart+courtesyLogoSize+courtesyGap+courtesyW+22,108);

        const headerText='ज्ञान अभ्यास परीक्षा';
        ctx.textAlign='center';
        ctx.fillStyle='#7b5a10';
        ctx.font=HEADER_FONT;
        ctx.fillText(headerText,800,181);

        const subjectText=certificateSubject;
        ctx.font='700 48px "Hind", sans-serif';
        const subjectW=Math.min(980,Math.max(650,ctx.measureText('विषय: '+subjectText).width+110));
        const subjectH=78;
        const subjectX=800-subjectW/2;
        const subjectY=207;
        const subjectGrad=ctx.createLinearGradient(subjectX,subjectY,subjectX+subjectW,subjectY+subjectH);
        subjectGrad.addColorStop(0,'#41436A');
        subjectGrad.addColorStop(.48,'#984063');
        subjectGrad.addColorStop(1,'#30c5ad');
        ctx.save();
        ctx.fillStyle=subjectGrad;
        roundedRect(subjectX,subjectY,subjectW,subjectH,20);
        ctx.fill();
        ctx.restore();
        ctx.fillStyle='#ffffff';
        ctx.fillText('विषय: '+subjectText,800,subjectY+52);

        const titleBoxX=505, titleBoxY=314, titleBoxW=590, titleBoxH=132;
        const titleGrad=ctx.createLinearGradient(titleBoxX,titleBoxY,titleBoxX+titleBoxW,titleBoxY+titleBoxH);
        titleGrad.addColorStop(0,'rgba(255,255,255,.88)');
        titleGrad.addColorStop(.5,'rgba(255,250,230,.96)');
        titleGrad.addColorStop(1,'rgba(245,250,246,.92)');
        ctx.fillStyle=titleGrad;
        roundedRect(titleBoxX,titleBoxY,titleBoxW,titleBoxH,38);ctx.fill();
        ctx.strokeStyle='#d39b24';ctx.lineWidth=4;ctx.stroke();
        ctx.strokeStyle='rgba(229,169,40,.55)';ctx.lineWidth=2;
        roundedRect(titleBoxX+11,titleBoxY+11,titleBoxW-22,titleBoxH-22,29);ctx.stroke();

        ctx.fillStyle='#765311';
        ctx.font=TITLE_FONT;
        ctx.textBaseline='middle';
        ctx.fillText('प्रमाणपत्र',800,380);

