    async function getCertificateFile(){
        if(!certificatePreview)return null;
        const response=await fetch(certificatePreview);
        const blob=await response.blob();
        return new File([blob],'bhajasi-certificate-'+(certificateId||'completion')+'.png',{type:'image/png'});
    }

    async function shareCertificate(){
        if(!certificatePreview)return;
        try{
            const file=await getCertificateFile();
            const shareSubject=String(selectedExam && selectedExam.title || 'ज्ञान परीक्षा').trim();
            const caption='मी भजसी भारत .com वरील '+shareSubject+' विषयावरील ज्ञान परीक्षा यशस्वीरीत्या उत्तीर्ण केली.\n\nभजसी भारत .com\nhttps://bhajasibharat.blogspot.com/\nनिर्मिती व संकलन: भरत रासवे';
            const shared = await shareImageFileNative(
                file,
                'भजसी भारत .com — '+shareSubject+' ज्ञान परीक्षा प्रमाणपत्र',
                caption
            );
            if(shared) navigate('examResult');
        }catch(error){
            console.error('Certificate share error:',error);
            alert('प्रमाणपत्र शेअर करता आले नाही. कृपया प्रतिमा जतन करून शेअर करा.');
        }
    }

    async function downloadCertificateImage(){
        if(!certificatePreview)return;
        try{
            const file=await getCertificateFile();
            if(!file)throw new Error('certificate file unavailable');
            const url=URL.createObjectURL(file);
            const a=document.createElement('a');a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();
            setTimeout(function(){URL.revokeObjectURL(url);},1500);
            setTimeout(function(){navigate('examResult');},250);
        }catch(error){alert('प्रतिमा जतन करता आली नाही.');}
    }

    async function downloadCertificatePDF(){
        if(!certificatePreview)return;
        try{
            if(!window.jspdf || !window.jspdf.jsPDF){
                await new Promise(function(resolve,reject){
                    const existing=document.querySelector('script[data-bhajasi-jspdf="1"]');
                    if(existing){
                        if(window.jspdf && window.jspdf.jsPDF){resolve();return;}
                        existing.addEventListener('load',resolve,{once:true});
                        existing.addEventListener('error',reject,{once:true});
                        return;
                    }
                    const script=document.createElement('script');
                    script.dataset.bhajasiJspdf='1';
                    script.src='https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js';
                    script.onload=resolve;
                    script.onerror=reject;
                    document.head.appendChild(script);
                });
            }

            const JsPDF=window.jspdf && window.jspdf.jsPDF;
            if(!JsPDF)throw new Error('jsPDF unavailable');

            const img=await new Promise(function(resolve,reject){
                const image=new Image();
                image.onload=function(){resolve(image);};
                image.onerror=reject;
                image.src=certificatePreview;
            });

            const pdf=new JsPDF({orientation:'landscape',unit:'mm',format:'a4'});
            const pageW=297;
            const pageH=210;
            const imageRatio=img.naturalWidth/Math.max(1,img.naturalHeight);
            const imageW=pageW;
            const imageH=imageW/imageRatio;
            const y=(pageH-imageH)/2;
            pdf.addImage(img,'PNG',0,y,imageW,imageH,undefined,'FAST');
            pdf.setProperties({
                title:'भजसी भारत .com — '+String(selectedExam && selectedExam.title || 'ज्ञान परीक्षा')+' ज्ञान परीक्षा प्रमाणपत्र',
                subject:'डिजिटल प्रमाणपत्र',
                author:'भरत रासवे'
            });
            pdf.save('bhajasi-certificate-'+(certificateId||'completion')+'.pdf');
            setTimeout(function(){navigate('examResult');},250);
        }catch(error){
            console.error('Certificate PDF error:',error);
            alert('PDF तयार करता आला नाही. कृपया पुन्हा प्रयत्न करा.');
        }
    }

